//! Parity tests for the ported upstream `experimental/` and `deprecated/`
//! plugins (gj first; msq and vsp follow the same pattern). The fixtures
//! under `testdata/experimental/<format>/` are generated by
//! `scripts/gen_experimental_fixtures.py` from the Python reference.

use std::path::PathBuf;

use libresvip_core::options::OptionValue;
use libresvip_core::plugin::SvsPlugin;
use libresvip_plugins::gj::PLUGIN as GJ_PLUGIN;
use libresvip_plugins::msq::PLUGIN as MSQ_PLUGIN;
use libresvip_plugins::ppsf::PLUGIN as PPSF_PLUGIN;
use libresvip_plugins::vsp::PLUGIN as VSP_PLUGIN;

fn workspace_root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("..")
        .join("..")
}

fn fixture_dir() -> PathBuf {
    workspace_root().join("testdata").join("experimental")
}

fn defaults(plugin: &'static dyn SvsPlugin, input: bool) -> libresvip_core::options::Options {
    let defs = if input {
        plugin.input_options()
    } else {
        plugin.output_options()
    };
    libresvip_core::options::Options::from_pairs(
        defs.into_iter()
            .map(|def| (def.key.to_owned(), def.default.clone())),
    )
}

/// Removes null entries everywhere (pydantic fixtures use `exclude_none`).
fn strip_nulls(value: &mut serde_json::Value) {
    match value {
        serde_json::Value::Object(map) => {
            map.retain(|_, value| !value.is_null());
            for value in map.values_mut() {
                strip_nulls(value);
            }
        }
        serde_json::Value::Array(items) => {
            for item in items {
                strip_nulls(item);
            }
        }
        _ => {}
    }
}

fn strip_bom(bytes: &[u8]) -> &[u8] {
    bytes.strip_prefix(&[0xEF, 0xBB, 0xBF]).unwrap_or(bytes)
}

#[test]
fn gj_round_trip_matches_python() {
    let root = fixture_dir().join("gj");
    let source = root.join("input.gj");
    assert!(
        source.is_file(),
        "missing fixture {}: generate it with scripts/gen_experimental_fixtures.py",
        source.display()
    );
    let plugin: &'static dyn SvsPlugin = &GJ_PLUGIN;
    let project = plugin
        .load(&source, &defaults(plugin, true))
        .expect("gj load");

    // 1. Structural parity: our hub model must equal Python's.
    let mut expected: serde_json::Value = serde_json::from_slice(
        &std::fs::read(root.join("expected_project.json")).expect("read expected project"),
    )
    .expect("parse expected project");
    strip_nulls(&mut expected);
    let mut actual = serde_json::to_value(&project).expect("serialize project");
    strip_nulls(&mut actual);
    assert_eq!(
        actual, expected,
        "the hub model parsed from input.gj differs from the Python reference"
    );

    // 2. Dump parity: pydantic's `exclude_none` drops None (and
    //    default_factory values) which serde spells differently; compare the
    //    parsed JSON with nulls dropped on both sides.
    let tmp = std::env::temp_dir().join(format!("libresvip-gj-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&tmp);
    std::fs::create_dir_all(&tmp).expect("create temp dir");
    let out = tmp.join("out.gj");
    plugin
        .dump(&out, &project, &defaults(plugin, false))
        .expect("gj dump");

    let expected_dump =
        std::fs::read(root.join("expected_dump.gj")).expect("read expected dump");
    let actual_dump = std::fs::read(&out).expect("read actual dump");
    let mut expected: serde_json::Value =
        serde_json::from_slice(strip_bom(&expected_dump)).expect("parse expected dump");
    let mut actual: serde_json::Value =
        serde_json::from_slice(strip_bom(&actual_dump)).expect("parse actual dump");
    strip_nulls(&mut expected);
    strip_nulls(&mut actual);
    if actual != expected {
        // First-divergence report: far more readable than dumping both trees.
        fn first_diff<'a>(a: &'a serde_json::Value, b: &'a serde_json::Value, path: &str, out: &mut Option<String>) {
            if out.is_some() { return; }
            match (a, b) {
                (serde_json::Value::Object(x), serde_json::Value::Object(y)) => {
                    for key in x.keys().chain(y.keys()) {
                        if x.get(key) != y.get(key) {
                            match (x.get(key), y.get(key)) {
                            (Some(a), Some(b)) => first_diff(a, b, &format!("{path}.{key}"), out),
                            _ => {}
                        }
                        }
                    }
                    if out.is_none() {
                        let only_us: Vec<_> = x.keys().filter(|k| !y.contains_key(*k)).collect();
                        let only_py: Vec<_> = y.keys().filter(|k| !x.contains_key(*k)).collect();
                        *out = Some(format!(
                            "{path}: ours-only {only_us:?}, python-only {only_py:?}"
                        ));
                    }
                }
                (serde_json::Value::Array(x), serde_json::Value::Array(y)) => {
                    if x.len() != y.len() {
                        *out = Some(format!("{path}: len {} vs {}", x.len(), y.len()));
                    } else {
                        for (index, (item_a, item_b)) in x.iter().zip(y.iter()).enumerate() {
                            if item_a != item_b {
                                first_diff(item_a, item_b, &format!("{path}[{index}]"), out);
                            }
                        }
                    }
                }
                _ => *out = Some(format!("{path}: {a:?} vs {b:?}")),
            }
        }
        let mut report = None;
        first_diff(&actual, &expected, "", &mut report);
        panic!("the re-dumped .gj differs from the Python reference: first diff at {}", report.unwrap_or_else(|| "?".to_owned()));
    }

    // 3. The upstream round trip is *lossy by design*:  shifts every
    //    note right by the first bar (first_bar_length) and  does not
    //    shift it back, so every load/dump cycle moves notes one bar to the
    //    right. Verified against Python: 1920 -> 3840 -> 5760 for this
    //    fixture. Assert we drift the exact same amount, not idempotence.
    let reloaded = plugin
        .load(&out, &defaults(plugin, true))
        .expect("reload our own dump");
    let shift = |value: &serde_json::Value| {
        value["TrackList"][0]["NoteList"][0]["StartPos"]
            .as_i64()
            .expect("start pos")
    };
    let before = shift(&serde_json::to_value(&project).expect("serialize project"));
    let after = shift(&serde_json::to_value(&reloaded).expect("serialize reloaded"));
    assert_eq!(
        after - before,
        1920,
        "expected the upstream one-bar drift, got {before} -> {after}"
    );

    let _ = std::fs::remove_dir_all(&tmp);
}

#[test]
fn msq_round_trip_matches_python() {
    let root = fixture_dir().join("msq");
    let source = root.join("input.msq");
    assert!(
        source.is_file(),
        "missing fixture {}: generate it with the Python battery",
        source.display()
    );
    let plugin: &'static dyn SvsPlugin = &MSQ_PLUGIN;
    let project = plugin
        .load(&source, &defaults(plugin, true))
        .expect("msq load");

    // 1. Hub model parity.
    let mut expected: serde_json::Value = serde_json::from_slice(
        &std::fs::read(root.join("expected_project.json")).expect("read expected project"),
    )
    .expect("parse expected project");
    strip_nulls(&mut expected);
    let mut actual = serde_json::to_value(&project).expect("serialize project");
    strip_nulls(&mut actual);
    assert_eq!(
        actual, expected,
        "the hub model parsed from input.msq differs from the Python reference"
    );

    // 2. Dump parity (JSON, nulls stripped; UUIDs normalized since Python
    //    generates fresh ones per dump).
    let tmp = std::env::temp_dir().join(format!("libresvip-msq-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&tmp);
    std::fs::create_dir_all(&tmp).expect("create temp dir");
    let out = tmp.join("out.msq");
    plugin
        .dump(&out, &project, &defaults(plugin, false))
        .expect("msq dump");

    let expected_dump =
        std::fs::read(root.join("expected_dump.msq")).expect("read expected dump");
    let actual_dump = std::fs::read(&out).expect("read actual dump");
    let mut expected: serde_json::Value =
        serde_json::from_slice(&expected_dump).expect("parse expected dump");
    let mut actual: serde_json::Value =
        serde_json::from_slice(&actual_dump).expect("parse actual dump");
    strip_nulls(&mut expected);
    strip_nulls(&mut actual);
    fn normalize_uuids(value: &mut serde_json::Value) {
        // 8-4-4-4-12 hex: fresh per dump, so blank them out before comparing.
        fn walk(value: &mut serde_json::Value, key_hint: bool) {
            match value {
                serde_json::Value::Object(map) => {
                    for (key, item) in map.iter_mut() {
                        let hint = key == "id" || key == "clip_id" || key == "track_id"
                            || key == "output" || key == "bus" || key == "primary_expression";
                        walk(item, hint);
                        let _ = key_hint;
                    }
                }
                serde_json::Value::Array(items) => {
                    for item in items.iter_mut() {
                        walk(item, key_hint);
                    }
                }
                serde_json::Value::String(text) if key_hint => {
                    let blanked = text
                        .split('-')
                        .map(|part| "0".repeat(part.len()))
                        .collect::<Vec<_>>()
                        .join("-");
                    *text = blanked;
                }
                _ => {}
            }
        }
        walk(value, false);
    }
    normalize_uuids(&mut expected);
    normalize_uuids(&mut actual);
    if actual != expected {
        panic!(
            "the re-dumped .msq differs from the Python reference:
ours:   {actual:#?}
python: {expected:#?}"
        );
    }

    let _ = std::fs::remove_dir_all(&tmp);
}

#[test]
fn vsp_round_trip_matches_python() {
    let root = fixture_dir().join("vsp");
    let source = root.join("input.vsp");
    assert!(
        source.is_file(),
        "missing fixture {}: generate it with scripts/gen_experimental_fixtures.py",
        source.display()
    );
    let plugin: &'static dyn SvsPlugin = &VSP_PLUGIN;
    let project = plugin
        .load(&source, &defaults(plugin, true))
        .expect("vsp load");

    // 1. Structural parity of the hub model.
    let mut expected: serde_json::Value = serde_json::from_slice(
        &std::fs::read(root.join("expected_project.json")).expect("read expected project"),
    )
    .expect("parse expected project");
    strip_nulls(&mut expected);
    let mut actual = serde_json::to_value(&project).expect("serialize project");
    strip_nulls(&mut actual);
    assert_eq!(
        actual, expected,
        "the hub model parsed from input.vsp differs from the Python reference"
    );

    // 2. Dump parity — the format is binary with no random identifiers, so
    //    the bytes must match exactly.
    let tmp = std::env::temp_dir().join(format!("libresvip-vsp-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&tmp);
    std::fs::create_dir_all(&tmp).expect("create temp dir");
    let out = tmp.join("out.vsp");
    plugin
        .dump(&out, &project, &defaults(plugin, false))
        .expect("vsp dump");
    let expected_dump = std::fs::read(root.join("expected_dump.vsp")).expect("read expected dump");
    let actual_dump = std::fs::read(&out).expect("read actual dump");
    if actual_dump != expected_dump {
        let mut first = None;
        for (index, (a, b)) in actual_dump.iter().zip(expected_dump.iter()).enumerate() {
            if a != b {
                first = Some((index, a, b));
                break;
            }
        }
        panic!(
            "the re-dumped .vsp differs from the Python reference: len {} vs {}, first diff {first:?}",
            actual_dump.len(),
            expected_dump.len()
        );
    }
    let _ = std::fs::remove_dir_all(&tmp);
}

#[test]
fn vsp_bgm_extraction_matches_python() {
    let root = fixture_dir().join("vsp");
    let source = root.join("bgm_input.vsp");
    assert!(source.is_file(), "missing fixture {}", source.display());

    let tmp = std::env::temp_dir().join(format!("libresvip-vsp-bgm-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&tmp);
    std::fs::create_dir_all(&tmp).expect("create temp dir");
    let input = tmp.join("input.vsp");
    std::fs::copy(&source, &input).expect("stage bgm fixture");

    let plugin: &'static dyn SvsPlugin = &VSP_PLUGIN;
    let options = libresvip_core::options::Options::from_pairs(
        plugin.input_options().into_iter().map(|def| {
            let value = if def.key == "extract_audio" {
                OptionValue::Bool(true)
            } else {
                def.default.clone()
            };
            (def.key.to_owned(), value)
        }),
    );
    let project = plugin.load(&input, &options).expect("vsp bgm load");

    let instrumental = project
        .track_list
        .iter()
        .filter_map(|track| match track {
            libresvip_core::model::base::Track::Instrumental(instrumental) => Some(instrumental),
            _ => None,
        })
        .next()
        .expect("expected the extracted bgm instrumental track");
    assert_eq!(instrumental.title, "input");
    assert!(
        instrumental.audio_file_path.ends_with("input.wav"),
        "unexpected audio path {}",
        instrumental.audio_file_path
    );

    // Our wave writer must produce the exact bytes Python's `wave` module did.
    let expected_wav = std::fs::read(root.join("bgm_expected.wav")).expect("read expected wav");
    let actual_wav = std::fs::read(input.with_extension("wav")).expect("read extracted wav");
    assert_eq!(actual_wav.len(), expected_wav.len(), "wav size mismatch");
    assert_eq!(actual_wav, expected_wav, "wav bytes differ");

    let _ = std::fs::remove_dir_all(&tmp);
}

#[test]
fn ppsf_legacy_round_trip_matches_python() {
    let root = fixture_dir().join("ppsf_legacy");
    let source = root.join("input.ppsf");
    assert!(
        source.is_file(),
        "missing fixture {}: generate it with scripts/gen_experimental_fixtures.py",
        source.display()
    );
    let plugin: &'static dyn SvsPlugin = &PPSF_PLUGIN;
    let project = plugin
        .load(&source, &defaults(plugin, true))
        .expect("ppsf legacy load");

    // 1. Structural parity of the hub model.
    let mut expected: serde_json::Value = serde_json::from_slice(
        &std::fs::read(root.join("expected_project.json")).expect("read expected project"),
    )
    .expect("parse expected project");
    strip_nulls(&mut expected);
    let mut actual = serde_json::to_value(&project).expect("serialize project");
    strip_nulls(&mut actual);
    assert_eq!(
        actual, expected,
        "the hub model parsed from input.ppsf differs from the Python reference"
    );

    // 2. Dump parity in the legacy binary format: byte-exact.
    let options = libresvip_core::options::Options::from_pairs(
        plugin
            .output_options()
            .into_iter()
            .map(|def| {
                let value = if def.key == "use_legacy_format" {
                    OptionValue::Bool(true)
                } else {
                    def.default.clone()
                };
                (def.key.to_owned(), value)
            }),
    );
    let tmp = std::env::temp_dir().join(format!("libresvip-ppsf-legacy-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&tmp);
    std::fs::create_dir_all(&tmp).expect("create temp dir");
    let out = tmp.join("out.ppsf");
    plugin.dump(&out, &project, &options).expect("ppsf legacy dump");
    let expected_dump =
        std::fs::read(root.join("expected_dump.ppsf")).expect("read expected dump");
    let actual_dump = std::fs::read(&out).expect("read actual dump");
    if actual_dump != expected_dump {
        let mut first = None;
        for (index, (a, b)) in actual_dump.iter().zip(expected_dump.iter()).enumerate() {
            if a != b {
                first = Some((index, a, b));
                break;
            }
        }
        panic!(
            "the re-dumped legacy .ppsf differs from the Python reference: len {} vs {}, first diff {first:?}",
            actual_dump.len(),
            expected_dump.len()
        );
    }

    // 3. Our dump parses back into the same hub model.
    let reloaded = plugin
        .load(&out, &defaults(plugin, true))
        .expect("reload our own dump");
    let mut reloaded_value = serde_json::to_value(&reloaded).expect("serialize reloaded");
    strip_nulls(&mut reloaded_value);
    assert_eq!(
        reloaded_value, expected,
        "reloading our legacy dump produced a different hub model"
    );
    let _ = std::fs::remove_dir_all(&tmp);
}

#[test]
fn msq_parsed_pitch_is_segmented_not_dense() {
    let root = fixture_dir().join("msq");
    let plugin: &'static dyn SvsPlugin = &MSQ_PLUGIN;
    let project = plugin
        .load(&root.join("input.msq"), &defaults(plugin, true))
        .expect("msq load");
    let pitch = project
        .track_list
        .first()
        .and_then(|track| match track {
            libresvip_core::model::base::Track::Singing(singing) => {
                Some(singing.edited_params.pitch.points.clone())
            }
            _ => None,
        })
        .expect("pitch");
    assert!(pitch.len() <= 12, "unexpectedly dense: {} points", pitch.len());
}

#[test]
fn relative_pitch_single_point_segment_stays_single() {
    use libresvip_plugins::mid::pitch::{PitchSimulator, Portamento, RelativePitchCurve};
    use libresvip_core::core::time_sync::TimeSynchronizer;
    use libresvip_core::model::base::{Note, SongTempo, TimeSignature};
    use libresvip_core::model::point::Point;
    let notes = vec![
        Note { start_pos: 480, length: 480, key_number: 60, lyric: "do".into(), ..Default::default() },
        Note { start_pos: 960, length: 480, key_number: 62, lyric: "re".into(), ..Default::default() },
    ];
    let tempos = vec![SongTempo::new(0, 120.0), SongTempo::new(1920, 150.0)];
    let sigs = vec![TimeSignature::new(0, 4, 4)];
    let synchronizer = TimeSynchronizer::from_project(&tempos);
    let simulator =
        PitchSimulator::new(&synchronizer, Portamento::no_portamento(), &notes, &sigs)
            .expect("simulator");
    let curve = RelativePitchCurve::new(1920);
    let single = vec![Point::new(2400, 6000)];
    let out = curve.from_absolute(&single, &simulator);
    assert_eq!(out.len(), 1, "single-point segment must stay single");
}
